UPDATE public.site_content
SET sq = 'Zbuloni misionin tonë, vlerat thelbësore dhe skuadrën e përkushtuar të vullnetarëve pas kësaj nisme. Ne jemi thellësisht të angazhuar për një të nesërme më të gjelbër, duke edukuar, përfshirë dhe frymëzuar komunitetin tonë lokal për të mbrojtur mjedisin dhe për të përqafuar praktika të qëndrueshme.',
    en = 'Discover our mission, values, and the dedicated volunteer team behind this initiative. We are deeply committed to fostering a greener tomorrow by actively educating, engaging, and inspiring our local community to protect the environment and embrace sustainable living practices.'
WHERE content_key = 'home_about_desc';

UPDATE public.site_content
SET sq = 'Mbrojtja e Planetit Tonë: Një nismë gjithëpërfshirëse për të ruajtur ekosistemet delikate, për të mbrojtur biodiversitetin dhe për të përballuar sfidat globale të klimës. Fokusi ynë aktual është marrja e masave proaktive për të mbrojtur pyjet tona nga zjarret gjatë sezonit të verës dhe për të ndërtuar një rezistencë afatgjatë klimatike në mbarë rajonin.',
    en = 'Protecting Our Planet: A comprehensive initiative to preserve fragile ecosystems, safeguard biodiversity, and tackle global climate challenges. We are currently focusing on proactive measures to protect our ancient forests from summer wildfires and build long-term climate resilience across the region.'
WHERE content_key = 'home_topic_desc';

UPDATE public.site_content
SET sq = 'Mësoni më shumë rreth programeve tona të larmishme edukative dhe shërbimeve profesionale mjedisore. Ne ofrojmë seminare të specializuara, trajnime praktike për riciklimin dhe konsulencë eksperte mbi praktikat e gjelbra për të ndihmuar individët dhe bizneset të reduktojnë në mënyrë efektive gjurmën e tyre ekologjike.',
    en = 'Learn more about our diverse educational programs and professional environmental services. We offer specialized workshops, hands-on recycling training, and expert consulting on green practices to help individuals and businesses effectively reduce their ecological footprint.'
WHERE content_key = 'home_services_desc';

UPDATE public.site_content
SET sq = 'Aktivitete të reja do të shtohen së shpejti.',
    en = 'New activities will be added soon.'
WHERE content_key = 'activities_empty';
